// In-page anchor support.
//
// Some source pages (ps11, ps12) open with their own table of contents linking to
// "#<slug>" targets. Those slugs were generated by Kramdown from the ORIGINAL heading
// text, so they must be derived from `headingEn` — deriving them from `headingHe`
// fails wherever a heading was normalised to the glossary (e.g. "יוניפיקציה" →
// "אוניפיקציה", "פרולוג" → "Prolog").
//
// Kramdown's rule, as observed in the sources: strip inline HTML, lowercase, drop
// punctuation, collapse whitespace runs to a single dash.

export function headingSlug(raw: string): string {
  return raw
    .replace(/<[^>]*>/g, " ") // titles may contain <br/>
    .toLowerCase()
    .replace(/[.,:;!?()[\]{}'"`״׳]/g, "")
    .trim()
    .replace(/\s+/g, "-");
}

/**
 * Resolve an in-page "#..." href to an element, tolerating URL-encoding.
 * Returns null when the anchor has no target on this page.
 */
export function findAnchorTarget(href: string): HTMLElement | null {
  const raw = href.slice(1);
  for (const candidate of [raw, decodeURIComponent(raw)]) {
    if (!candidate) continue;
    const el = document.getElementById(candidate);
    if (el) return el;
  }
  return null;
}
